-- W-M2 E1 reconciliation through the metric views (contract of 01-spec/oracle/metrics/W-M2.sql).
-- Generated by build_reconciliation_queries.py; edit the generator, not this file.
SELECT grain, measure, member_1, member_2, member_3, value
FROM (
  SELECT 'total' AS grain, 'W-M2' AS measure, CAST(NULL AS STRING) AS member_1, CAST(NULL AS STRING) AS member_2, CAST(NULL AS STRING) AS member_3, MEASURE(closing_units) AS value
  FROM slc.semantic.wwi_stock
  UNION ALL
  SELECT 'year' AS grain, 'W-M2' AS measure, CAST(YEAR(snapshot_year) AS STRING) AS member_1, CAST(NULL AS STRING) AS member_2, CAST(NULL AS STRING) AS member_3, MEASURE(closing_units) AS value
  FROM slc.semantic.wwi_stock
  GROUP BY snapshot_year
  UNION ALL
  SELECT 'month' AS grain, 'W-M2' AS measure, CAST(snapshot_month AS STRING) AS member_1, CAST(NULL AS STRING) AS member_2, CAST(NULL AS STRING) AS member_3, MEASURE(closing_units) AS value
  FROM slc.semantic.wwi_stock
  GROUP BY snapshot_month
  UNION ALL
  SELECT 'day' AS grain, 'W-M2' AS measure, CAST(snapshot_date AS STRING) AS member_1, CAST(NULL AS STRING) AS member_2, CAST(NULL AS STRING) AS member_3, MEASURE(closing_units) AS value
  FROM slc.semantic.wwi_stock
  GROUP BY snapshot_date
  UNION ALL
  SELECT 'fiscal_year' AS grain, 'W-M2' AS measure, CAST(snapshot_fiscal_year AS STRING) AS member_1, CAST(NULL AS STRING) AS member_2, CAST(NULL AS STRING) AS member_3, MEASURE(closing_units) AS value
  FROM slc.semantic.wwi_stock
  GROUP BY snapshot_fiscal_year
  UNION ALL
  SELECT 'year_stock_item' AS grain, 'W-M2' AS measure, CAST(YEAR(snapshot_year) AS STRING) AS member_1, stock_item AS member_2, CAST(NULL AS STRING) AS member_3, MEASURE(closing_units) AS value
  FROM slc.semantic.wwi_stock
  GROUP BY snapshot_year, stock_item
  UNION ALL
  SELECT 'year_color' AS grain, 'W-M2' AS measure, CAST(YEAR(snapshot_year) AS STRING) AS member_1, color AS member_2, CAST(NULL AS STRING) AS member_3, MEASURE(closing_units) AS value
  FROM slc.semantic.wwi_stock
  GROUP BY snapshot_year, color
  UNION ALL
  SELECT 'year_stock_group' AS grain, 'W-M2' AS measure, CAST(YEAR(snapshot_year) AS STRING) AS member_1, stock_group AS member_2, CAST(NULL AS STRING) AS member_3, MEASURE(closing_units) AS value
  FROM slc.semantic.wwi_stock_by_stock_group
  GROUP BY snapshot_year, stock_group
) r
ORDER BY grain, measure, member_1 NULLS FIRST, member_2 NULLS FIRST, member_3 NULLS FIRST
